{"cards": [{"node_code": "N_34c75607acf2a793", "definition": "研究儿童期神经系统发育异常、脑病及遗传代谢性疾病的临床特征、诊断评估与长期管理策略，涵盖癫痫、脑瘫及代谢筛查。", "boundary": "本节点聚焦于儿童特有的神经病理及全身性遗传代谢病。包括先天性脑发育畸形、儿童期癫痫综合征、脑瘫康复及遗传代谢病的酶替代治疗。与“儿科学·神经系统疾病”的区别在于，本节点强调遗传代谢机制及全身多系统受累，而后者侧重局灶性神经结构或功能病变。", "includes": ["儿童癫痫、脑瘫及神经发育障碍的诊疗", "遗传代谢病的筛查、基因诊断与代谢干预", "先天性脑发育畸形及神经管缺陷管理"], "excludes": ["成人神经退行性疾病（归入神经病学）", "单纯性儿童行为心理障碍（归入儿童精神卫生）"], "sibling_distinctions": [{"other_code": "N_6baf90219bbd8552", "rule": "本节点侧重遗传代谢机制及全身性代谢异常导致的神经症状；“儿科学·神经系统疾病”侧重儿童脑部结构、感染或外伤等局灶性神经病变。"}, {"other_code": "N_501ddf8f9d8d539c", "rule": "本节点侧重遗传代谢病及神经发育障碍；“生长发育与内分泌”侧重激素轴功能异常及生长曲线偏离，除非代谢病直接由内分泌腺体病变引起。"}], "cross_boundary_rule": "涉及儿童遗传代谢病时，若侧重基因诊断与分子机制，可关联医学遗传学；若侧重临床表型管理与儿科护理，主挂载本节点。"}, {"node_code": "N_b3ba711c066bfc38", "definition": "研究儿童免疫系统发育特点、原发性免疫缺陷、过敏性疾病及儿童风湿性疾病的发病机制、诊断标准与免疫调节治疗。", "boundary": "本节点涵盖儿童特有的免疫病理过程，包括先天性免疫缺陷、自身免疫性风湿病（如幼年特发性关节炎）及严重过敏反应。与“儿童感染性疾病”的区别在于，本节点关注免疫系统本身的功能异常或过度反应，而非单纯的外源性病原体感染。", "includes": ["原发性免疫缺陷病的诊断与免疫球蛋白替代治疗", "儿童风湿免疫病（如系统性红斑狼疮、川崎病）管理", "儿童过敏性疾病（如哮喘、特应性皮炎）的免疫机制与干预"], "excludes": ["由明确病原体引起的急性感染（归入儿童感染性疾病）", "成人特异性风湿病（归入成人风湿免疫科）"], "sibling_distinctions": [{"other_code": "N_87042295f7954e76", "rule": "本节点侧重免疫系统自身缺陷或自身免疫反应；“儿童感染性疾病”侧重细菌、病毒等病原体引起的感染及其抗感染治疗。"}, {"other_code": "N_a872a4bc78a2867b", "rule": "本节点侧重全身性免疫调节及过敏性机制；“儿科学·呼吸系统疾病”侧重呼吸道局部结构或感染性病变，除非哮喘等病以免疫机制为核心。"}], "cross_boundary_rule": "涉及儿童过敏性哮喘时，若侧重气道炎症与呼吸功能管理，主挂载呼吸系统疾病；若侧重全身免疫机制与多系统过敏表现，主挂载本节点。"}, {"node_code": "N_a872a4bc78a2867b", "definition": "研究儿童呼吸道解剖生理特点、常见感染性、阻塞性及先天性呼吸道疾病的诊断、治疗及呼吸支持技术。", "boundary": "本节点聚焦于儿童呼吸系统局部病变，包括肺炎、支气管炎、哮喘急性发作、先天性气道畸形及呼吸衰竭管理。与“免疫与风湿病”的区别在于，本节点侧重呼吸道局部病理及通气/换气功能，而非全身免疫机制。", "includes": ["儿童肺炎、支气管炎及哮喘的诊疗", "先天性气道畸形（如喉软骨软化）及气管异物处理", "儿童呼吸衰竭的机械通气与呼吸支持"], "excludes": ["全身性免疫缺陷导致的反复感染（归入免疫与风湿病）", "成人特异性肺部疾病（归入成人呼吸内科）"], "sibling_distinctions": [{"other_code": "N_b3ba711c066bfc38", "rule": "本节点侧重呼吸道局部病变及通气功能；“免疫与风湿病”侧重全身免疫机制及过敏性疾病的免疫调节。"}, {"other_code": "N_87042295f7954e76", "rule": "本节点侧重呼吸道特异性感染及气道管理；“儿童感染性疾病”涵盖全身各系统感染，若呼吸道感染为全身感染的一部分，需结合主要受累系统判断。"}], "cross_boundary_rule": "涉及儿童哮喘时，若侧重气道炎症与呼吸功能管理，主挂载本节点；若侧重全身免疫机制与多系统过敏表现，主挂载免疫与风湿病。"}]}
